<template><section class="item-tray party-tray" :aria-label="`${label} 아이템`"><header><strong>{{ label }} <span v-if="state.guard>0">✨ 보호 {{ Math.ceil(state.guard/1000) }}초</span><span v-else-if="state.shield>0">🛡️ 방패 {{ Math.ceil(state.shield/1000) }}초</span><span v-else-if="slow>0">🫧 여유 {{ Math.ceil(slow/1000) }}초</span></strong><small>{{ cooldown>0?`${Math.ceil(cooldown/1000)}초 대기`:`${Math.ceil(next/1000)}초 후 아이템 블록` }}</small></header><div class="item-slots"><button v-for="slot in [0,1,2]" :key="slot" :data-item-slot="slot" :class="state.inventory[slot]||'empty-slot'" :disabled="disabled||cooldown>0||!state.inventory[slot]" :aria-label="state.inventory[slot]?`${label} ${ITEMS[state.inventory[slot]!]!.name} 사용`:`${label} 빈 아이템 칸`" :title="state.inventory[slot]?ITEMS[state.inventory[slot]!]!.description:'아이콘이 든 블록을 줄과 함께 지워 획득'" @click="$emit('use',slot)"><span>{{ state.inventory[slot]?ITEMS[state.inventory[slot]!]!.icon:'＋' }}</span><b>{{ state.inventory[slot]?ITEMS[state.inventory[slot]!]!.name:'블록 수집' }}</b><kbd>{{ keys[slot] }}</kbd></button></div><p role="status">{{ state.noticeTime>0?state.notice:'아이템 블록을 줄과 함께 지우세요 · V/B/N으로 사용' }}</p></section></template>
<script setup lang="ts">
import {ITEMS,type ItemState} from '~/game/GameModes'
defineProps<{state:ItemState;label:string;keys:string[];disabled:boolean;next:number;slow:number;cooldown:number}>();defineEmits<{use:[slot:number]}>()
</script>
<style scoped>
.item-tray{border:2px solid #fff;border-radius:18px;padding:8px 11px 5px;background:linear-gradient(120deg,#6535b7,#c7449b);color:white;min-width:0;box-sizing:border-box;box-shadow:0 4px 12px #55257425}.item-tray header{display:flex;justify-content:space-between;align-items:center;gap:8px;font:700 10px -apple-system,Arial}.item-tray header span{color:#ffffa6;margin-left:5px}.item-tray header small{font-size:9px;white-space:nowrap}.item-slots{display:flex;gap:6px;margin-top:6px}.item-slots button{display:flex;align-items:center;justify-content:center;gap:5px;flex:1;min-width:0;min-height:44px;border:1px solid #fff8;border-radius:12px;color:#fff;background:#ffffff20;cursor:pointer;touch-action:manipulation}.item-slots button:active:not(:disabled){background:#ffffff50}.item-slots button:focus-visible{outline:3px solid #ffe358}.item-slots button:disabled{opacity:.55;cursor:default}.item-slots span{font-size:21px}.item-slots b{font:700 9px -apple-system,Arial}.item-slots kbd{font-size:8px;background:#0003;padding:2px;border-radius:3px}.item-tray p{font:600 9px -apple-system,Arial;margin:5px 0;min-height:11px;color:#fff2b0}@media(max-width:700px){.item-slots button{gap:3px}.item-slots span{font-size:20px}}
